export const PRODUCT = {

recruitment: {
  packages: ["educationcloud"],
  name: "Recruitment",
  icon: "\u{1F4E3}",
  color: "#3b82f6",
  description: "Recruitment in Education Cloud manages prospective learner engagement from initial identification and inquiry through application readiness. It captures information through the Education Portal, represents unengaged suspects as Leads, and creates Person Accounts when individuals signal interest. Campaigns, recruitment events, staff outreach, and the Student Recruitment Agent help institutions inform and nurture prospects, while recruitment analytics show funnel performance. Directors and recruiters organize prospect assignments and advance qualified prospects into admissions applications.",
  components: [
    {id:"prospect-management",name:"Prospect Management",icon:"\u{1F465}",desc:"Prospect Management distinguishes suspects who have not indicated interest from prospects who have engaged with the institution. Education Cloud stores suspects as Lead records and converts them to Person Accounts after they signal interest. Recruiters can then use the person record to provide more personalized engagement and prepare qualified prospects for the application process.",tags:["Lead","ContactProfile"],docs:["Education Cloud uses Lead and Person Account records to represent different stages of prospective learner engagement. A Lead represents a suspect who has not yet indicated interest, such as an individual imported from a testing-service list. When that individual requests information or otherwise signals interest, the Lead can be converted to a Person Account representing the prospect. Institutions can define criteria to promote suspects to prospects automatically or manually.","The Education Portal collects information from prospective learners when they request information, apply for admission, upload documents, or schedule appointments. Recruiters use the Recruitment & Admissions app to respond to information requests, manage appointments, track work, and communicate application requirements and deadlines. The Student Recruitment Agent can also create an academic interest when a person requests recruiter contact and can create an inquiry when a question requires human attention."],docUrl:"https://developer.salesforce.com/docs/platform/data-models/guide/recruitment-and-admissions.html",connections:[{"planet":"admissions","desc":"Qualified prospects submit applications"},{"planet":"records","desc":"Prospect data flows into person records"}]},
    {id:"campaign-management",name:"Campaign Management",icon:"\u{1F4E8}",desc:"Campaign Management supports targeted engagement with suspects and prospects across recruitment activities. Education Cloud CRM data can be synchronized with Marketing Cloud Engagement for Industries to create email campaigns, including application deadline reminders and recruiting appointment details. Campaign information also supports campus tour and event discovery by the Student Recruitment Agent.",tags:["Campaign","CampaignMember"],docs:["Institutions can synchronize Education Cloud CRM data with Marketing Cloud Engagement for Industries to create email campaigns. Documented recruitment uses include application deadline reminders and recruiting appointment details. In the prospect-management example, a recruiting team sends targeted marketing emails to Lead records and responds when a recipient requests more information.","Campaigns also support recruitment event experiences. The Student Recruitment Agent includes actions that retrieve campus tour campaigns and create campus tour registrations. Supporting flows retrieve planned campaigns for authenticated or unauthenticated agent experiences, with unauthenticated implementations requiring administrators to clone and configure the documented flow templates."],connections:[{"planet":"analytics","desc":"Campaign metrics feed recruitment dashboards"}]},
    {id:"recruitment-events",name:"Recruitment Events",icon:"\u{1F3AA}",desc:"Recruitment Events help institutions engage prospective learners through college fairs, on-campus events, conferences, campus tours, and visits. Recruiters represent their institutions at these activities and support prospects with information about programs, requirements, and deadlines. Education Cloud also lets prospective learners discover and register for campus activities through the Student Recruitment Agent.",tags:["Campaign","CampaignMember"],docs:["Recruiters can represent an institution at college fairs, on-campus events, conferences, and other recruitment events. The Recruitment & Admissions consoles help staff manage daily and upcoming work by displaying tasks and Event list views. Recruiters can also create and manage appointments with prospective learners as part of the recruitment process.","The Student Recruitment Agent provides information about campus tours, visits, and events and can assist users with registration. Its campus-event capabilities retrieve available campus tour campaigns and create a campus tour registration. For unauthenticated access, administrators clone and configure the documented campaign, person-account processing, and campus-tour registration flows."],connections:[{"planet":"experience","desc":"Event registration through the prospect portal"}]},
    {id:"recruitment-communications",name:"Recruitment Communications",icon:"\u{1F4EC}",desc:"Recruitment Communications provides personalized outreach and information to prospective learners. Recruiters can respond to information requests, explain application requirements and deadlines, and use synchronized CRM data for recruiting email campaigns. The Student Recruitment Agent extends this engagement by answering grounded questions, capturing interest, and escalating unanswered conversations to staff.",tags:["ContactPointEmail","ContactPointPhone"],docs:["The Education Portal gives prospective learners an online channel to request information and schedule appointments with support staff. Information submitted through the portal is recorded in Salesforce, where recruiters can manage requests and related follow-up. Marketing Cloud Engagement for Industries can synchronize Education Cloud CRM data for communications such as application deadline reminders and recruiting appointment details.","The Student Recruitment Agent answers questions about the institution, learning programs, support programs, application processes, and campus information. Institutions ground its answers with public-facing Salesforce Knowledge articles aligned to those areas. The agent can also record a request for recruiter contact by creating an academic interest for a specified learning program.","Some prospective learner questions require personal attention rather than an automated response. Institutions can configure an escalation subagent to redirect unanswered conversations to a human representative. The Create Inquiry action can then create a case, an educational information request, and an academic interest raised by a prospective learner, parent, or counselor."],connections:[{"planet":"agentforce","desc":"Recruitment agent automates outreach sequences"}]},
    {id:"territory-management",name:"Territory Management",icon:"\u{1F5FA}",desc:"Territory Management supports recruitment work organized around geographic or other institution-defined prospect segments. Recruitment directors can create actionable prospect lists and assign them to staff, while recruiters work the resulting prospects and activities. Recruitment analytics help directors and recruiters monitor progress and focus their engagement.",tags:["Lead"],docs:["Education Cloud supports region-focused recruitment processes through prospect data and staff assignments. In the documented example, a recruiting team imports a list of prospective learners from the East Coast as Lead records and directs targeted outreach to that population. When a person responds and indicates interest, a recruiter converts the Lead to a Person Account for more personalized engagement.","The Recruitment & Admissions Director Console gives directors a place to view recruitment analytics, create actionable lists, and assign those lists to staff. The Recruiter Console combines Recruitment Insights with daily tasks and upcoming events. These consoles allow institutions to organize prospect coverage and monitor assigned recruitment work without separating prospect information from related activities and analytics."],connections:[{"planet":"analytics","desc":"Territory performance feeds recruitment analytics"}]}
  ],
  dataFlow: ["Capture prospect inquiries and event registrations through the Education Portal.","Create Lead records for suspects who have not yet indicated interest.","Convert interested suspects into Person Accounts and related person records.","Nurture prospects through campaigns, recruiter communications, and AI recruitment agent outreach.","Assign regional or actionable prospect lists and monitor the funnel with recruitment dashboards.","Move qualified prospects into the admissions application process."],
  connections: [{"planet":"admissions","desc":"Qualified prospects move to applications"},{"planet":"records","desc":"Prospect data creates person records"},{"planet":"agentforce","desc":"AI recruitment agent automates outreach"},{"planet":"experience","desc":"Prospect portal for inquiry and events"},{"planet":"analytics","desc":"Recruitment funnel dashboards"}]
},

admissions: {
  packages: ["educationcloud"],
  name: "Admissions",
  icon: "\u{1F4CB}",
  color: "#6366f1",
  description: "Admissions in Education Cloud manages applications from recruited prospects through online submission, document collection, staff review, and final decisions. Applicant information is stored on person records, while the Education Portal lets applicants complete tasks, upload materials, and track status; an AI agent can answer applicant questions. The process also connects with application fees and financial aid packaging. When an applicant is admitted, the learner can proceed into program enrollment.",
  components: [
    {id:"application-management",name:"Application Management",icon:"\u{1F4C4}",desc:"Application Management supports the admissions lifecycle in Education Cloud from application creation through submission, withdrawal, and preparation for review. Applicants use the Education Portal to create applications, complete application tasks, upload materials, and monitor application details and statuses. Available application choices are driven by active Program Term Application Timeline records and their related academic terms, learning programs, and application timelines. Submitted applicant information is recorded in Education Cloud for admissions staff to manage.",tags:["IndividualApplication","Applicant"],docs:["Dynamic applications provide applicants with a guided process for applying to available learning programs. The New Application window can present application type, academic term, and learning program choices based on qualified Program Term Application Timeline records. Related academic terms and learning programs must be active, and the related application timeline must be open. The portal can operate in self mode or proxy mode so that users apply for themselves or, when configured, on behalf of another person.","Institutions can configure the Application Details component to let applicants view and edit application tasks before submission. They can enable submission after required tasks are complete and optionally require a digital signature and confirmation statements. After submission, applicants can view task details but can no longer edit them. Institutions can also allow applicants to cancel unsubmitted applications or withdraw submitted applications.","The Education Portal provides an Applications area that lists a portal user’s applications with their statuses and details. Portal users can start new applications from this area and track existing applications alongside tasks and appointments. Permission sets, system permissions, and audiences control which portal users can access the relevant pages and components. Applicant information collected through the portal is stored in Salesforce records for use by admissions staff."],docUrl:"https://developer.salesforce.com/docs/platform/data-models/guide/recruitment-and-admissions.html",connections:[{"planet":"recruitment","desc":"Applications originate from recruited prospects"},{"planet":"enrollment","desc":"Admitted students proceed to enrollment"}]},
    {id:"document-tracking",name:"Document Tracking",icon:"\u{1F4CE}",desc:"Document Tracking records the materials associated with an admissions application and whether each item is required, received, or still outstanding. Applicants can upload admissions documents through the Education Portal and work with file-related application tasks before submission. Admissions staff can use checklist status and receipt information to monitor application completeness. The tracked items remain associated with their parent application record.",tags:["DocumentChecklistItem"],docs:["The Education Portal supports online collection of admissions documents as part of the application experience. When application task viewing and editing are enabled, applicants can update supported application stages, including Files, until they submit the full application. After submission, applicants can continue to view task details but can’t edit them. This provides a controlled transition from applicant preparation to staff processing.","Document checklist items identify application materials and track whether they are required and whether they have been received. Their status and received date give staff a record of document completion for the associated parent record. Admissions staff can use this information with other application tasks when determining whether an application is ready for subsequent processing."],connections:[]},
    {id:"application-review",name:"Application Review",icon:"\u{1F50D}",desc:"Application Review supports structured staff evaluation of submitted applications in Education Cloud. Application Review records capture rubric results, reviewer comments, and recommendations. Reviews can be assigned to staff and surfaced through the Admissions Console or Reviewer Console. Institutions can also use flows and scoring rubrics to automate and accelerate parts of the review process.",tags:["IndividualApplication"],docs:["An Application Review represents a staff member’s evaluation of an application. The review can include scoring-rubric results, comments, and a recommendation that informs later admissions work. Education Cloud supports flows for automating the application review process. Dynamic applications and configurable scoring rubrics help institutions tailor review-related processes to their requirements.","Assigned work is available through role-focused console pages. The Admissions Console can include a My Reviews list alongside applications that are ready for decision, while the Reviewer Console can display the reviewer’s Application Review records directly. Both console patterns can also show tasks and upcoming events. Access is assigned through the Recruitment & Admissions app and selected user profiles.","Institutions can configure an Application Review Lightning record page with a highlights panel, record details, related lists, and activities. The page must be activated to make it available to users. Salesforce recommends removing Notes & Attachments from the page layout’s related lists to avoid duplication when using the configured record page."],connections:[]},
    {id:"admissions-decisions",name:"Admissions Decisions",icon:"\u{2705}",desc:"Admissions Decisions manages the final, publicly releasable outcome of an application in Education Cloud. An Application Decision can represent outcomes such as admit, enroll, waitlist, deny, or cancel. Applications that have completed prerequisite processing can be surfaced to staff in a Ready for Decision list. Decision information then supports the applicant’s transition from admissions to enrollment when applicable.",tags:["IndividualApplication","Applicant"],docs:["An Application Decision records the final outcome that can be released for an application. Admissions staff can work from the Admissions Console, where a Ready for Decision list can display qualifying Individual Application records. The same console can place decision-ready applications beside assigned reviews, tasks, events, and admissions analytics. This gives staff a central view of work leading into final decisions.","Institutions can create an Application Decision record page in Lightning App Builder. The documented layout includes a highlights panel, tabs for record details and related lists, and a separate activity area. Administrators activate the page to make it visible to the appropriate users. Salesforce recommends removing Notes & Attachments from the related lists on the page layout to prevent duplication."],connections:[{"planet":"financials","desc":"Admission triggers financial aid packaging"}]},
    {id:"preliminary-applications",name:"Preliminary Applications",icon:"\u{1F4DD}",desc:"Preliminary Applications hold application work in progress before an applicant submits it. They preserve initial information such as the intended program, intended term, status, and associated person account. Dynamic application configuration determines which programs and terms applicants can select. On submission, Education Cloud automatically creates a Preliminary Application Record and an Individual Application record.",tags:["PreliminaryApplication"],docs:["Applicants begin an application from the Education Portal’s Applications area. Available application types, academic terms, and learning programs are derived from qualified Program Term Application Timeline records. A qualifying timeline is connected to active academic term and learning program records and has an application window that is currently open. The applicant’s selections therefore reflect configured admissions offerings.","The New Application component can be configured for self mode or proxy mode. Self mode lets a user apply on their own behalf, while proxy mode lets a user apply for themselves or another person available through contacts related to the running user’s account. Configuration can permit preliminary applications for more than one program. When the applicant submits, Education Cloud automatically creates both a Preliminary Application Record and an Individual Application record.","Before submission, applicants can complete and revise supported application tasks when editing is enabled. Institutions can require completion of application tasks, applicant confirmation, and a digital signature before accepting submission. They can also allow cancellation of an unsubmitted application and control whether canceled or withdrawn applications appear in the portal list. These options are configured on Education Portal application components and take effect after the site is published."],connections:[{"planet":"recruitment","desc":"Preliminary apps bridge recruitment and admissions"}]},
    {id:"admissions-console",name:"Admissions Console",icon:"\u{1F5A5}",desc:"The Admissions Console is a role-focused home page for admissions work in the Education Cloud Recruitment & Admissions app. It presents high-level insights about applicant status together with assigned reviews, decision-ready applications, tasks, and events. Administrators build and configure the page in Lightning App Builder and assign it to selected profiles. Education Analytics can provide the embedded Recruitment and Admissions Insights dashboard.",tags:["IndividualApplication"],docs:["The Admissions Console gives admissions staff a single home-page view of application work and admissions data. A documented configuration places the Recruitment and Admissions Insights dashboard at the top of the page. Tabs can display Individual Application records that are ready for decision and Application Review records assigned to the current user. Today’s tasks and upcoming events can appear in a separate column.","Administrators create the console as a Lightning home page and add the required dashboard, tabs, list views, task, and event components. Education Analytics must be set up before its dashboard can be selected. After saving the page, the administrator activates it for the Recruitment & Admissions app and assigns it to the profiles that require access. Setting up the console requires Education Cloud Full Access and CRM Analytics for Education Cloud Admin permissions.","Education Cloud also documents related consoles for directors, recruiters, and reviewers. Directors can view recruitment and admissions analytics, recruiters can see recruitment insights with tasks and events, and reviewers can focus on their assigned Application Review records. These role-oriented home pages are separately configured and activated for the Recruitment & Admissions app. Permission sets and profiles determine which Education Cloud records, components, and app pages each staff role can use."],connections:[{"planet":"agentforce","desc":"Admissions agent answers applicant questions"}]}
  ],
  dataFlow: ["Convert recruited prospects into applicant person records and begin their applications.","Collect application details and documents through the applicant portal, with an AI agent answering applicant questions.","Track application fees and connect applicant information used for financial aid packaging.","Submit applications and route completed records for assigned review and rubric-based evaluation.","Record and release the final admissions decision, and expose application status in the portal.","Advance admitted students into program enrollment."],
  connections: [{"planet":"recruitment","desc":"Applications originate from recruited prospects"},{"planet":"records","desc":"Applicant data stored on person records"},{"planet":"enrollment","desc":"Admitted students enroll in programs"},{"planet":"financials","desc":"Application fees and financial aid packaging"},{"planet":"agentforce","desc":"AI agent answers applicant questions"},{"planet":"experience","desc":"Applicant portal for status tracking"}]
},

academics: {
  packages: ["educationcloud"],
  name: "Academic Operations",
  icon: "\u{1F3EB}",
  color: "#8b5cf6",
  description: "Academic Operations is the structural foundation for managing the programs, courses, academic periods, scheduled offerings, and learning objectives maintained by an institution. Education Cloud provides a central app and specialized learning data model for creating these records, managing their relationships, and publishing program plans. Programs and courses define what learners enroll in and provide structure for tuition calculation, while transfer credits connect external study to student education history. Learning objectives and achievements connect curriculum with competency and learner-progress tracking in Student Success.",
  components: [
    {id:"program-management",name:"Program Management",icon:"\u{1F393}",desc:"Program Management provides a central way to create and maintain the academic programs offered by an institution. Programs organize curriculum, requirements, and related learning records that support recruitment, enrollment, degree planning, and learner progress. Program structures also provide course and credit information used by student financial processes.",tags:["Program"],docs:["Academic Operations is the central location for creating and maintaining learning-related objects and their relationships. Staff can use Learning Wizard to create programs, courses, and customized academic offerings. These records become a foundation for processes in Recruitment and Admissions and Student Success.","Staff can use Learning Program Plan Builder to create, manage, visualize, and publish program plans. Plans can organize required courses, electives, reusable collections, and categories for a particular catalog or cohort. Published plans flow to Intelligent Degree Planning and inform the Learner Progress View.","Program requirements can include prerequisites, corequisites, and recommendations. Education Cloud can validate prerequisite and corequisite requirements in a learner pathway, either automatically when configured or through the available verification action. Program and course structures define what learners can enroll in and provide inputs for tuition calculation."],docUrl:"https://developer.salesforce.com/docs/platform/data-models/guide/academic-operations.html",connections:[{"planet":"enrollment","desc":"Students enroll in programs"},{"planet":"success","desc":"Program requirements drive learning plans"}]},
    {id:"course-management",name:"Course Management",icon:"\u{1F4DA}",desc:"Course Management maintains the courses and related curriculum information that make up an institution’s academic catalog. Course records can be associated with prerequisites, corequisites, recommendations, learning outcomes, and learning achievements. The resulting course structure supports enrollment, scheduling, tuition calculation, and learner progress processes.",tags:["Course"],docs:["Staff can use Academic Operations and Learning Wizard to create and maintain courses and customized academic offerings. Course and curriculum data form the basis of the institution’s course catalog. These learning records are also used by Recruitment and Admissions and Student Success tools.","Education Cloud supports foundational requirements for courses, including prerequisites, corequisites, and recommendations. Learning foundation items can be associated with learning outcomes and achievements to model these relationships. When pathway validation is enabled, Education Cloud can automatically validate prerequisite and corequisite requirements when a learner drops a course from the pathway canvas.","Course records provide the academic definition used to create scheduled course offerings. Programs and courses define what learners enroll in, while course structure provides information used by student financial processes to apply tuition and fees. Course-related outcomes also connect academic work with learner competency and achievement tracking."],connections:[]},
    {id:"course-offerings",name:"Course Offerings",icon:"\u{1F4C5}",desc:"Course Offerings represent scheduled instances of courses within the institution’s academic calendar. They connect course information with a term, section, capacity, delivery mode, and related schedule details. Faculty and teaching assistant assignments associate instructors with the specific offerings they support.",tags:["CourseOffering"],docs:["Academic Operations enables staff to create and schedule courses and other academic offerings. A course offering applies the definition of a course to a specific scheduled instance, allowing the institution to organize sections within academic periods. Offering and schedule data contribute to the course catalog used by learners and staff.","Education Cloud provides configurable record pages for course offering schedules and course offering schedule templates. These pages can present record details, related lists, and activity in Lightning Experience. Institutions can activate the configured pages to make them available to users with the appropriate access.","Course offering participation records track learner involvement in an offering, including enrollment, completion, drop, and waitlist states. The offering therefore connects the academic catalog and schedule with enrollment activity. Its course structure and academic interval also provide context for tuition and fee calculation."],connections:[{"planet":"enrollment","desc":"Students register for course offerings"},{"planet":"appointments","desc":"Academic advising precedes course registration"}]},
    {id:"academic-terms",name:"Academic Terms",icon:"\u{1F4C6}",desc:"Academic Terms define the dated periods used to organize registration, course scheduling, and academic reporting. Terms provide the time context for course offerings and can contain more granular academic time periods. This structure aligns scheduled learning activity with enrollment and financial processing.",tags:["AcademicTerm","AcademicTimePeriod"],docs:["Academic calendars organize institutional time through academic years, terms, and sessions. Academic term dates establish when a period begins and ends, while registration dates identify its enrollment window. Course offerings are scheduled within this calendar structure.","Academic schedule data is part of the foundation for the institution’s course catalog. Linking offerings to terms enables learners and staff to understand when courses are available. The same academic intervals provide timing context for loading and applying tuition and fees to learning programs and courses."],connections:[{"planet":"financials","desc":"Terms drive tuition fee schedules"}]},
    {id:"learning-objectives",name:"Learning Objectives",icon:"\u{1F3AF}",desc:"Learning Objectives define the intended outcomes associated with academic courses. They document what a learning activity is expected to address and how the objective is assessed. These objectives connect course design with learning achievements and competency tracking in Student Success.",tags:["LearningObjective"],docs:["Academic Operations can be configured to define learning outcomes and manage the learning records related to them. Staff can manage learning outcome items and learning foundation items and associate them with learning achievements. A learning achievement represents the outcome of learning activity, such as completing a course, program, degree, diploma, skill, or achievement group.","Learning objectives provide course-level context for expected outcomes and assessment. Related outcome records map learning activity to achievements, while foundational items capture prerequisites, corequisites, recommendations, or other learning requirements. These relationships allow academic outcomes to contribute to competency and learner-progress tracking."],connections:[{"planet":"success","desc":"Objectives map to competency assessments"}]},
    {id:"transfer-credits",name:"Transfer Credits & Equivalencies",icon:"\u{1F504}",desc:"Transfer Credits & Equivalencies records learning completed at another institution and maps it to internal courses. Transfer credit information connects recognized external study with a learner’s education history. Equivalency mappings support evaluation of how external coursework can satisfy internal academic requirements.",tags:["TransferCredit","LearningEquivalency"],docs:["Transfer credit records capture originating institutions, original course information, and the amount of credit associated with prior study. They link the evaluated credit to the applicable learner account and education history. This preserves the relationship between an individual learner and recognized external coursework.","Learning equivalencies map an external course and institution to an internal course and credit value. Staff can use these mappings as the academic basis for transfer credit evaluation. Recognized credit can then be considered alongside the programs, courses, and requirements managed in Academic Operations."],connections:[{"planet":"records","desc":"Transfer credits link to student education history"}]}
  ],
  dataFlow: ["Define programs, courses, requirements, and learning objectives.","Organize academic terms and schedule course offerings within them.","Publish program and course structures for learner enrollment and planning.","Use course and academic-interval data to drive tuition calculation.","Evaluate transfer credits against learning equivalencies and link results to student education history.","Connect learning objectives and achievements to competency tracking in Student Success."],
  connections: [{"planet":"enrollment","desc":"Programs and courses define what students enroll in"},{"planet":"records","desc":"Transfer credits link to student education history"},{"planet":"financials","desc":"Course structure drives tuition calculation"},{"planet":"success","desc":"Learning objectives tie to competency tracking"}]
},

enrollment: {
  packages: ["educationcloud"],
  name: "Enrollment",
  icon: "\u{1F4D6}",
  color: "#0ea5e9",
  description: "Enrollment in Education Cloud tracks learner participation in academic programs, terms, and course offerings after an admission decision. It connects enrollment transactions to person accounts and to the courses, programs, schedules, and academic periods maintained in Academic Operations. Course registration supports policy enforcement, holds, waitlists, status changes, fee calculation, and advising requirements. Grades, credits, GPA information, achievements, and learning plans provide progress data for degree planning and student success tracking.",
  components: [
    {id:"program-enrollment",name:"Program Enrollment",icon:"\u{1F3C1}",desc:"Program Enrollment represents a learner’s participation in an institutional program after the admissions process. It connects the learner to the relevant program and supports tracking of enrollment status, start date, expected graduation, and cumulative GPA. Program enrollment information is available to staff through student records and enrollment-history views. Changes such as declaring or abandoning a major can also drive student success workflows and advisor assignments.",tags:["ProgramEnrollment"],docs:["Education Cloud models courses, programs, enrollment requirements, and completion requirements through its education data model. Before enrolling learners, an institution sets up its academic calendar and creates the applicable learning programs and related program plans in Academic Operations. These academic records provide the program and term context for enrollment. Enrollment records are connected to learner records so that staff can access enrollment data alongside other student information.","Program enrollment follows the admissions process and can be associated with the academic term in which an admitted applicant enrolls. Education Cloud provides a flow template that assigns an academic advisor and advising team when a learner declares a major, then removes those assignments if the learner abandons it. Institutions configure this automation with their learning program plans, case record type, advisors, and predefined case teams. Program enrollment information can also appear in an Enrollment History timeline with academic term enrollments and course offering participants."],connections:[{"planet":"admissions","desc":"Enrollment follows admission decisions"},{"planet":"records","desc":"Enrollment links to student person records"}]},
    {id:"course-registration",name:"Course Registration",icon:"\u{1F4DD}",desc:"Course Registration manages learner participation in scheduled course offerings. Advanced Academic Operations provides course registration, waitlists, holds management, enrollment policy enforcement, and related student portal features. Registrations reference the courses, offerings, schedules, and academic periods maintained in Academic Operations. Registration can trigger fee calculation and may depend on completion of a required advising appointment.",tags:["CourseOfferingParticipant"],docs:["A course offering is a scheduled instance of a learning course, and its schedules tell learners when and where the class meets. Course registration associates a learner with that offering through a Course Offering Participant record. The participant record carries the learner’s role, registration status, and credit mode in the context of the selected offering. Course, program, curriculum, and schedule data established in Academic Operations provide the foundation for the registration experience.","Advanced Academic Operations extends Education Cloud with course registration, waitlists, holds management, GPA calculation, and enrollment policy enforcement. Students need the applicable Advanced Academic Operations for Experience Cloud license and permission sets to use course registration, waitlists, and student portal features. The feature set uses Business Rules Engine and Expression Sets, and its features require the associated quota capacity. Registration also connects with institutional financial processes for fee calculation and with appointment management when advising is required."],connections:[{"planet":"academics","desc":"Registration references course offerings"},{"planet":"financials","desc":"Registration triggers fee calculation"}]},
    {id:"academic-achievement",name:"Academic Achievement",icon:"\u{1F3C6}",desc:"Academic Achievement records the results of a learner’s academic activity, including grades, credits attempted, credits earned, and quality points. Learning achievements can be associated with learning outcome items and learning foundation items defined in Academic Operations. These records support GPA-related processes and progress tracking across courses and programs. Achievement and grade information can also be harmonized in Data 360 for Education Cloud for analytics and unified learner insights.",tags:["LearningAchievement"],docs:["Education Cloud uses Learning Achievement records to represent outcomes from learning activities, such as completed courses, programs, credentials, skills, or achievement groups. Academic Operations lets staff manage learning outcome items and learning foundation items and associate them with learning achievements. The recorded grade and credit information provides evidence of completed or attempted academic work. Learning Achievement has public read-only default internal access in the documented Student Management setup.","Education systems can exchange enrollment and assessment data through supported integration connectors. Bi-directional integrations can synchronize course structures and assessment components and push final and component grades from a learning management system to a student information system. Advanced Academic Operations includes GPA calculation, while student success flow templates can react to failed course participation or an academic term GPA that falls below an institution’s configured threshold. Data 360 for Education Cloud also provides LearningAchievement and related education data model objects for harmonization, calculated insights, and analytics."],connections:[{"planet":"success","desc":"Achievements feed student success tracking"}]},
    {id:"enrollment-status",name:"Enrollment Status Management",icon:"\u{1F4CA}",desc:"Enrollment Status Management tracks changes in a learner’s participation in programs, academic terms, and course offerings. It supports operational states such as enrolled, waitlisted, dropped, completed, and withdrew, as well as cart and hold-related states used during registration. Advanced Academic Operations applies enrollment policies and manages holds and waitlists around these transactions. Status information gives staff a current view of enrollment and provides context for student success follow-up.",tags:["ProgramEnrollment"],docs:["Education Cloud maps institution-facing participant picklist values to standardized registration states. Documented mappings include Enrolled to ENROLLED, Waitlisted to WAITLISTED, Dropped to DROPPED, Withdrew to WITHDREW, Completed to COMPLETED, and In Cart or On Hold to IN_CART. Other values, including Audit, Facilitating, Failed, Transfer Credit, and Declined Waitlist, map to the appropriate documented registration categories. These mappings provide consistent status handling while allowing institutions to expose process-specific labels.","Advanced Academic Operations supports holds management, waitlists, and enrollment policy enforcement as part of course registration. Staff can configure a Course Offering Participant record page to make participation information available in Education Cloud. Academic term enrollment records can likewise use a Lightning record page containing record details, related lists, and activity. Enrollment-history timelines can combine academic term enrollments, learner programs, and course offering participants into a chronological view for staff."],connections:[{"planet":"financials","desc":"Financial holds affect enrollment status"}]},
    {id:"learning-plans",name:"Learning Plans",icon:"\u{1F5FA}",desc:"Learning Plans organize the academic requirements and planned work associated with a learner’s program. Academic Operations provides Learning Program Plan Builder for creating, managing, visualizing, and publishing program plans. Published plans flow into Intelligent Degree Planning and inform the Learner Progress View. Learner-specific plan information can track target completion and planned-credit totals while supporting advising and student success conversations.",tags:["LearningPlan"],docs:["Learning Program Plan Builder is a visual tool for structuring the requirements used to deliver a learning program. Staff can organize required courses, electives, reusable collections, and categories within a program plan. Anyone creating program plans needs sharing and edit access to the relevant learning objects. Institutions can also create learning program plans for major fields of study and associate each plan with its related learning program.","Plans created in Learning Program Plan Builder flow to Intelligent Degree Planning, which helps learners and advisors organize courses and evaluate program requirements. The resulting planning information informs the Learner Progress View used in learner support. Education Cloud also models learner pathways, pathway items, learner programs, program requirements, and requirement progress for learner-specific tracking. Advisors can use this academic context during appointments and when monitoring student success."],connections:[{"planet":"success","desc":"Learning plans support student success tracking"},{"planet":"appointments","desc":"Plan adjustments often require advising appointments"}]}
  ],
  dataFlow: ["Record the admission outcome and establish the learner’s program enrollment against the linked person account.","Reference the applicable program, academic term, curriculum, and learning plan.","Register the learner in course offerings while enforcing policies, holds, and waitlist rules.","Schedule any required advising appointment and trigger fee calculation from the course registration.","Update enrollment statuses and record grades, credits, GPA information, and learning achievements.","Feed enrollment and achievement progress into student success tracking and learner support."],
  connections: [{"planet":"admissions","desc":"Enrollment follows admission decisions"},{"planet":"academics","desc":"Enrollment references courses, programs, and terms"},{"planet":"records","desc":"Enrollment records link to person accounts"},{"planet":"success","desc":"Enrollment progress feeds student success tracking"},{"planet":"financials","desc":"Course registration triggers fee calculation"},{"planet":"appointments","desc":"Registration may require advising appointments"}]
},

records: {
  packages: ["educationcloud"],
  name: "Student Records",
  icon: "\u{1F464}",
  color: "#10b981",
  description: "Student Records is the person-centered data domain that anchors the learner lifecycle in Education Cloud. It uses Person Accounts to centralize identity, demographics, contact points, relationships, education history, examinations, languages, employment, and enrollment-related information in an accessible student view. Recruitment and admissions create and enrich these records, while academics, enrollment, student success, financials, mentoring, alumni engagement, and appointment management reference the same person identity. Data 360 for Education Cloud resolves duplicate identities so institutional data can contribute to a unified learner profile.",
  components: [
    {id:"person-accounts",name:"Person Accounts",icon:"\u{1F464}",desc:"Person Accounts represent individual students, applicants, staff, faculty, alumni, and external contacts in Education Cloud. They combine account and contact information in a single Account record, providing the central identity used throughout the learner lifecycle. Configurable Account record pages give authorized staff a consolidated view of details, relationships, education, employment, engagement, and related records.",tags:["Account"],docs:["Education Cloud stores information about individual people as Person Accounts on the Account object. An institution must enable Person Accounts and create the required Account record types, including Business Account, Secondary School, and College. After Education Cloud is enabled, it can’t be disabled.","Institutions can create Account record pages for students and alumni in Lightning App Builder and make them the defaults for the Student Success and Alumni Relations apps. The documented student page can include record details, relationships, education, employment, engagement, interest tags, and related records. A prospect record page can similarly combine a person profile, timeline, actions, related lists, appointment scheduling, and engagement tools.","Access to Person Account data is controlled through Salesforce security features, including organization-wide defaults, profiles, permission sets, role hierarchies, sharing rules, and field-level security. Institutions subject to FERPA or HIPAA requirements must account for protected student information in their security model. Education Cloud recommends coordinating Salesforce configuration with institutional security, legal, and regulatory requirements."],connections:[{"planet":"enrollment","desc":"Person accounts are the identity anchor for enrollments"},{"planet":"admissions","desc":"Applicants are linked to person accounts"}]},
    {id:"contact-points",name:"Contact Points",icon:"\u{1F4DE}",desc:"Contact Points maintain the address, phone, and email information associated with a person record in Education Cloud. Each contact point can capture its usage and, for phone and email records, whether it is the primary contact method. These details contribute to the centralized student record available to authorized staff and faculty.",tags:["ContactPointAddress","ContactPointPhone","ContactPointEmail"],docs:["The Student Management app centralizes student contact information with emergency contacts, relationships, and enrollment data. This consolidated view gives staff and faculty quick access to important information without separating it from the broader student record. Access can be assigned to institutional users such as advisors, registrars, and faculty.","ContactPointAddress records capture named addresses and their street, city, state, postal code, country, and usage type. ContactPointPhone and ContactPointEmail records associate telephone numbers or email addresses with a parent record and identify their usage and primary status. Institutions can use Salesforce access controls to restrict who can view or edit this information."],connections:[]},
    {id:"relationships",name:"Relationships & Household",icon:"\u{1F46A}",desc:"Relationships & Household connects students with emergency contacts, related people, and household contexts in Education Cloud. Relationship information can be presented visually on Person Account pages through an Actionable Relationship Center graph. These connections also support third-party scenarios in which parents, guardians, or agents manage information for represented students.",tags:["ContactRelationship"],docs:["The Student Management app can show emergency contacts and relationships directly in student records. Institutions can add a relationship graph to communicate a student’s connections to households. On a student Account record page, the ARC Relationship Graph component can be placed on a dedicated Relationships tab.","Setting up the documented Person Account relationship graph requires allowing contacts to be related to multiple accounts, enabling Group Membership, and creating a graph from Education Cloud Person Account Relations. Applicant portals can also let parents, guardians, and agents manage students they represent. When a third party adds a student, Education Cloud creates relationship records that support sharing application information."],connections:[{"planet":"mentoring","desc":"Mentoring profiles reference person relationships"}]},
    {id:"education-history",name:"Education History",icon:"\u{1F4DC}",desc:"Education History records a person’s prior institutional study, including institutions, degrees, dates, and academic results. Education Cloud can display Person Education records alongside academic credentials on the student Account record page. This history informs transfer credit evaluation and can also contribute to alumni engagement views.",tags:["PersonEducation"],docs:["A student Account record page can include an Education tab with related lists for Person Education and Person Academic Credentials. This configuration makes prior education information available from the same person-centered workspace as student details and other related records. Access to the records depends on the page, object, field, and sharing permissions configured by the institution.","PersonEducation is included among the Education Cloud objects mapped for Student Success data in Data 360 for Education Cloud. The Alumni Relations Console can also report learning achievements that alumni earned from the institution or from other institutions. Within the broader learner lifecycle, prior education history provides information used during transfer credit evaluation."],connections:[{"planet":"academics","desc":"Education history informs transfer credit evaluation"}]},
    {id:"examinations",name:"Examinations & Test Scores",icon:"\u{1F4DD}",desc:"Examinations & Test Scores associates examination records with an individual’s Person Account in Education Cloud. A record can identify the examination, its date, the total score, and section-level scores. Examination data is part of the student-related information that can be mapped into Data 360 for Education Cloud.",tags:["PersonExamination"],docs:["PersonExamination records preserve examination details for an individual, including ExamName, ExamDate, TotalScore, and SectionScores. AccountId connects each examination record to the corresponding person record. This association keeps test information tied to the learner identity used across Education Cloud.","PersonExamination is included in the documented set of Student Success objects mapped by the Education data kit. Once mapped into Data 360 for Education Cloud, education data can participate in the institution’s harmonized learner data. Access to the source records remains subject to the institution’s configured Salesforce security model."],connections:[{"planet":"admissions","desc":"Test scores inform admission decisions"}]},
    {id:"demographics-languages",name:"Demographics & Languages",icon:"\u{1F30D}",desc:"Demographics & Languages maintains personal profile details and a learner’s language information in Education Cloud. Person Account fields provide core identifying information, while PersonLanguage records capture language, proficiency, and primary-language status. These details remain associated with the central person record used by learner-facing and staff-facing processes.",tags:["PersonLanguage","PersonEmployment"],docs:["Person Accounts combine account and contact information into a single record for students, applicants, faculty, staff, alumni, and other individuals. Core Account information can include the person’s name, birthdate, student identifier, email, and record type. The Record Detail component can expose permitted profile fields on configured student, alumni, and prospect record pages.","PersonLanguage records associate a language and proficiency level with a person through AccountId. The IsPrimary field indicates whether the language is designated as primary for that person. PersonLanguage is also included among the Student Success objects mapped by the Education data kit for Data 360 for Education Cloud."],connections:[{"planet":"alumni","desc":"Employment data tracks post-graduation outcomes"}]}
  ],
  dataFlow: ["Create or update Person Accounts from prospect data, and retain applicant information on those person records.","Add contact points, relationships, education history, examinations, languages, and employment details to the learner’s record.","Use the person identity for enrollment and appointment records, and use education history during transfer credit evaluation.","Link student-success competencies and traits and mentoring mentor or mentee profiles to the person record.","Connect financial accounts to the person and track the person’s alumni status as the learner lifecycle progresses.","Resolve duplicate identities in Data 360 for Education Cloud to support a unified learner profile."],
  connections: [{"planet":"recruitment","desc":"Prospect data creates person records"},{"planet":"admissions","desc":"Applicant data stored on person records"},{"planet":"academics","desc":"Education history informs transfer credit evaluation"},{"planet":"enrollment","desc":"Student identity for all enrollment records"},{"planet":"success","desc":"Competencies and traits linked to person"},{"planet":"financials","desc":"Financial accounts linked to person records"},{"planet":"mentoring","desc":"Mentor/mentee profiles reference person records"},{"planet":"alumni","desc":"Alumni status tracked on person records"},{"planet":"appointments","desc":"Appointments reference student records"},{"planet":"data360","desc":"Identity resolution unifies duplicate person records"}]
},

success: {
  packages: ["educationcloud"],
  name: "Student Success",
  icon: "\u{1F31F}",
  color: "#22c55e",
  description: "Student Success in Education Cloud brings together learner information, advising cases, success teams, care plans, alerts, appointments, programs, and analytics to provide proactive, personalized support. It helps institutions monitor academic progress, competencies, interests, career and life goals, course performance, and mentoring outcomes in the context of unified person records. Advisors can identify learners who need assistance, coordinate interventions, and collaborate with learners through staff consoles and self-service portal components. The Agentforce for Education Cloud advising agent can surface at-risk learners, while analytics and KPIs help institutions assess engagement and student success.",
  components: [
    {id:"competency-tracking",name:"Competency Tracking",icon:"\u{1F4AA}",desc:"Competency Tracking associates learner competencies and proficiency information with person records in Education Cloud. PersonCompetency records capture the competency name, proficiency level, assessment date, and assessment method for an Account. Learning objectives from Academic Operations provide academic context for competency tracking, while the resulting information contributes to the institution’s view of learner progress.",tags:["PersonCompetency"],docs:["Competency Tracking uses PersonCompetency records to represent competencies associated with individual learners. Each record can identify the competency, the learner’s proficiency level, when the assessment occurred, and the assessment method. AccountId connects the competency information to the learner’s person record.","Learning objectives defined through academic operations tie academic activity to competency tracking. Education Cloud can place this information alongside academic progress and other learner data so staff have a more complete view of the learner’s journey. Institutions can use that view when providing personalized learner support."],connections:[{"planet":"academics","desc":"Learning objectives map to competency assessments"}]},
    {id:"traits-affinities",name:"Traits & Affinities",icon:"\u{1F9E0}",desc:"Traits & Affinities captures structured information about a learner’s characteristics and interests on person-associated records. PersonTrait records identify a trait’s name, category, and strength, while PersonAffinity records identify an affinity’s name, type, and interest level. This information complements interest tags and shared-interest data used to understand learners and support personalized engagement.",tags:["PersonTrait","PersonAffinity"],docs:["PersonTrait records associate categorized traits with a learner’s Account. The Name, Category, and Strength fields describe the trait and its relative strength for that person. PersonAffinity records similarly associate named interests with an Account and capture an affinity type and interest level.","Education Cloud student record pages can include the Interest Tags component, giving staff a place to view interest-related information in the learner context. Mentoring programs can connect learners and mentors based on shared interests and goals. These person-level details can therefore contribute to a more complete learner profile without replacing advising, care-plan, or academic records."],connections:[]},
    {id:"advising",name:"Academic Advising",icon:"\u{1F91D}",desc:"Academic Advising provides case-based, collaborative support for learners across academics, financial aid, careers, and life goals. Advisors can work with advising cases, success teams, personalized care plans, alerts, tasks, analytics, and appointments from the Student Success app. Learners can use portal components to view advisors and support information, manage tasks, and schedule appointments.",tags:["CareCoordinator","CareRole"],docs:["Education Cloud supports case-based advising by connecting each learner’s support request with the staff responsible for it. Institutions configure a support process and create Case record types for advising scenarios, then create success teams associated with case record types and case teams. Care plans can be enabled to organize personalized goals, tasks, benefits, and interventions.","The advisor console is available in the Student Success app and requires no additional home-page setup. Advisors can create and assign care plans, create alerts, view student success analytics, and review advisor insights and KPIs. Directors can use a configured Student Success console to review learners without success teams, open alerts, advisor lists, institutional KPIs, events, and tasks.","Advising record pages can bring together cases, academic term enrollments, interaction summaries, appointments, and staff scheduling. The advising Case page can also include separate views for upcoming, in-progress, and completed appointments and record alerts, along with open activities. Salesforce Scheduler enables learners and staff to arrange in-person, phone, and virtual advising appointments that support interventions."],docUrl:"https://developer.salesforce.com/docs/platform/data-models/guide/student-success.html",connections:[{"planet":"appointments","desc":"Advising sessions scheduled as appointments"},{"planet":"agentforce","desc":"AI advising agent surfaces at-risk students"}]},
    {id:"academic-alerts",name:"Academic Alerts",icon:"\u{26A0}",desc:"Academic Alerts notify staff about learner performance or another condition that requires attention. Education Cloud supports alerts for attendance, behavior, courses, academics, careers, financial aid, and housing. Advisors and directors can review alerts alongside cases, care plans, analytics, appointments, and other learner information to coordinate timely support.",tags:["Case"],docs:["Education Cloud can create alerts that notify staff about learner performance. In K–12 scenarios, alerts can identify learners who need support based on attendance, behavior, and courses. Higher education teams can manage alerts related to academics, careers, financial aid, and housing.","Advisors can create alerts from the Student Success advisor console, and directors can use dashboard views focused on open alerts. The advising Case record page can be configured with related lists for upcoming, in-progress, and completed record alerts. This places alert review in the same workspace as appointments, tasks, and the learner’s advising case.","Course performance from enrollment activity can feed student success interventions, and configurable alert thresholds determine when monitored conditions warrant attention. The Agentforce for Education Cloud advising agent can surface at-risk learners, while staff use advising cases, success teams, care plans, and appointments to manage the response. Analytics dashboards and student success KPIs help institutions monitor learner engagement and the effectiveness of support processes."],connections:[{"planet":"enrollment","desc":"Enrollment data triggers academic alerts"}]},
    {id:"career-development",name:"Career Development",icon:"\u{1F680}",desc:"Career Development supports focused advising and mentoring around learners’ career goals and related milestones. Learners can set, update, and track specific, measurable, achievable, relevant, and time-bound career and life goals through Student Success portal components. Mentors and advisors can help learners identify goals, consider career paths, and plan actions such as internships, job searches, and professional networking.",tags:["PersonCompetency","PersonAffinity"],docs:["Student Success portal components allow learners to manage SMART career and life goals. Learners can also view care plans, goals, benefits, tasks, action plans, success-team members, and assigned advisors. These self-service capabilities give learners a central place to track goal-related work and obtain support.","Education Cloud mentoring programs can support professional and personal development in addition to academic success. Mentors can help mentees identify career goals, develop a roadmap, explore career paths, and consider internships or job searches. Mentoring outcomes feed into success tracking so that career-related support can be considered with the learner’s broader progress and interventions."],connections:[{"planet":"alumni","desc":"Alumni career data informs current student planning"}]}
  ],
  dataFlow: ["Connect academic learning objectives to learner competency records and proficiency assessments.","Bring course enrollment performance and mentoring outcomes into student success tracking.","Store competencies, traits, affinities, and success metrics on records associated with each learner.","Evaluate performance against configured alert thresholds and use the Agentforce for Education Cloud advising agent to surface at-risk learners.","Create or update advising cases, assign success teams, and organize interventions through care plans and tasks.","Schedule advising appointments, deliver interventions, and track learner progress and outcomes."],
  connections: [{"planet":"academics","desc":"Learning objectives tie to competency tracking"},{"planet":"enrollment","desc":"Course performance feeds success interventions"},{"planet":"records","desc":"Success metrics stored on person records"},{"planet":"mentoring","desc":"Mentoring outcomes feed into success tracking"},{"planet":"appointments","desc":"Advising appointments support interventions"},{"planet":"agentforce","desc":"AI advising agent surfaces at-risk students"}]
},

financials: {
  packages: ["educationcloud"],
  name: "Student Financials",
  icon: "\u{1F4B0}",
  color: "#f59e0b",
  description: "Student Financials in Education Cloud bridges learners and their financial accounts by managing tuition, fees, financial aid, balances, invoices, and payment access. Products, price books, fee schedules, pricing rules, Academic Orders, and order products translate academic and enrollment activity into student charges, including admissions-related fees. Financial records connect to person records, while financial aid and scholarship information can support admissions packaging and alumni and advancement processes. Education Portal self-service, Student Financials and Financial Aid agents, and analytics dashboards help learners and staff understand account details and financial health.",
  components: [
    {id:"fee-management",name:"Fee Management",icon:"\u{1F4B5}",desc:"Fee Management in Education Cloud provides the framework for loading tuition and fees by academic interval and applying them to learning programs and courses. Institutions can model fee types as products and use pricing structures to address differences such as residency-based tuition, lab fees, and meal plan charges. Generated fees become part of the learner’s financial account information and can be explained through portal components and the Student Financials Agent.",tags:["Product2"],docs:["Fee Management connects institutional fee definitions with the academic structure maintained in Education Cloud. Institutions load tuition and fees for each academic interval, then associate applicable fees with learning programs and courses. This approach allows program and course information from Academic Operations to drive the charges created for learners.","Learners can review account balances and detailed fee breakdowns through an Education Cloud portal. The Student Financials Agent can retrieve balances and explain fee amounts, descriptions, and optional fee types for specific academic terms. Its fee-management actions query academic terms, academic term enrollments, academic orders, order products, billing schedules, invoices, invoice lines, and credit memos."],connections:[{"planet":"academics","desc":"Course and program structure determines applicable fees"}]},
    {id:"price-books",name:"Price Books & Schedules",icon:"\u{1F4D5}",desc:"Price Books & Schedules in Education Cloud organize the products and prices used to represent institutional tuition and fees. Products define chargeable fee items, while price books and price book entries associate those items with active unit prices. These structures support fee schedules driven by academic intervals, programs, and courses.",tags:["Pricebook2","PricebookEntry"],docs:["Institutions use products and price books to model their fee catalog in Education Cloud. A product identifies a tuition or fee item, and a price book groups prices that can be applied in a particular fee structure. A price book entry connects a product to a price book and records its unit price and active status.","Fee schedules can reflect the academic context in which charges apply. Program and course structures provide the basis for applying tuition and fees, while pricing rules address scenarios such as in-state versus out-of-state tuition, lab fees, and meal plan charges. Product access can also be exposed as read-only to Experience Cloud users when configuring student financial self-service."],connections:[]},
    {id:"academic-orders",name:"Academic Orders",icon:"\u{1F6D2}",desc:"Academic Orders in Education Cloud represent student charges generated from applicable tuition and fee structures. An order associates charges with a student account, academic term, effective date, status, and total amount. Its order products provide the individual fee lines used for detailed account and fee explanations.",tags:["AcademicOrder","OrderProduct"],docs:["Academic Orders translate applicable fee definitions into charges for a learner. Registration can trigger tuition charges, while the learner’s program, courses, and academic term determine which fee schedules apply. Each order records the resulting total, and its order products identify the products, quantities, unit prices, and line totals included.","Academic Orders also support student financial self-service and agent responses. The Student Financials Agent queries Academic Order and Order Product records to retrieve account history, provide fee breakdowns, and explain individual fees. Student access requires appropriate object permissions, field-level access, and sharing for the related account and academic term enrollment records."],connections:[{"planet":"enrollment","desc":"Course registration triggers order generation"}]},
    {id:"payment-processing",name:"Payment Processing",icon:"\u{1F4B3}",desc:"Payment Processing in Education Cloud supports student access to financial status, invoices, and payment options through an Education Portal. Institutions configure a merchant account and add payment methods before exposing student financial account management. Sharing and permissions restrict learners to the invoice and financial records they are authorized to access.",tags:["AcademicOrder"],docs:["To enable portal payments, an institution configures a merchant account and adds payment methods to it. The Education Portal can then include student financial components, including Financial Status at a Glance, for authenticated learners. Required access includes student financials, billing, and Experience Cloud permissions.","Portal configuration provides students with controlled access to invoices and related financial information. Education Cloud setup uses private external access for invoices and a sharing set so each student can access the appropriate invoice records. Credit memos, products, academic periods, and billing schedule groups can be made readable where required for the financial experience."],connections:[{"planet":"enrollment","desc":"Financial holds can block registration"}]},
    {id:"financial-aid",name:"Financial Aid",icon:"\u{1F381}",desc:"Financial Aid in Education Cloud gives staff, prospects, and students access to applications, awards, cost estimates, requirements, and disbursements. Data 360 harmonizes information from an external financial aid management system and grounds both financial aid components and the Financial Aid Agent. Financial aid data can be shown on Person Account pages and in an Education Portal, with access controlled by identity verification and data-governance policies.",tags:["AcademicOrder","OrderProduct"],docs:["Education Cloud models the financial aid lifecycle in Data 360 from application through award assignment and disbursement. Financial aid data from an external management system is ingested and mapped to education-specific data model objects for applications, benefits, required documents, costs, disbursement periods, disbursements, holds, and academic standing. Identity resolution connects those records to Salesforce Person Accounts and unified learner information.","Financial aid components can be added to an Education Portal for students and prospects or to a Person Account record page for staff. Available views cover highlights, cost and aid overviews, checklists, applications, awards, disbursements, and notifications. A Financial Aid Year Filter supplies data to the other components and lets users select an academic award year.","The Financial Aid Agent answers questions about financial aid status, requirements, awards, estimated cost of attendance, disbursement dates, and satisfactory academic progress. Authenticated students can use their existing portal identity, while unauthenticated prospects must complete one-time password verification before receiving personalized information. The agent provides factual answers only and cannot accept awards, submit documents or applications, change aid packages, or provide financial advice."],connections:[{"planet":"admissions","desc":"Financial aid packaging tied to admission offers"}]}
  ],
  dataFlow: ["Define tuition and fee products, price books, schedules, and rules from academic program and course structures.","Apply admissions application fees and financial aid packaging, and link resulting financial information to the learner’s person record.","Trigger Academic Orders and order products from enrollment and registration activity for the applicable academic term.","Present balances, fee details, invoices, financial aid, and payment options through the Education Portal.","Use Student Financials and Financial Aid agents to answer billing, fee, account, and aid questions, and connect scholarship funding with alumni and advancement activity.","Monitor student financial health, charges, aid, and payment information through analytics dashboards."],
  connections: [{"planet":"admissions","desc":"Application fees and financial aid packaging"},{"planet":"enrollment","desc":"Registration triggers tuition charges"},{"planet":"academics","desc":"Program and course structure drives fee schedules"},{"planet":"records","desc":"Financial accounts linked to person records"},{"planet":"alumni","desc":"Scholarship funds connect to advancement"},{"planet":"agentforce","desc":"Financial aid agent answers billing questions"},{"planet":"experience","desc":"Student financial self-service portal"},{"planet":"analytics","desc":"Financial health dashboards"}]
},

mentoring: {
  packages: ["educationcloud"],
  name: "Mentoring",
  icon: "\u{1F91D}",
  color: "#f472b6",
  description: "Mentoring in Education Cloud supports structured programs that connect mentees with mentors for academic, professional, and personal development. Facilitators define programs and benefits, collect assessment and profile information, compare potential mentors, and manage relationships through benefit assignments. Mentor and mentee profiles connect to person records, mentoring sessions can be scheduled as appointments, and program outcomes can be evaluated as student success metrics.",
  components: [
    {id:"program-design",name:"Program Design",icon:"\u{1F4CB}",desc:"Program Design enables facilitators to create and manage mentoring programs in Education Cloud and define the benefits they contain. Programs can support networking, skill development, academic guidance, career development, and other mentoring needs. Learners can enroll through an Experience Cloud portal, while assessments help facilitators understand participant requirements and goals.",tags:["MentoringProgram"],docs:["The Education Cloud Mentoring app supports programs that connect mentees with mentors and deliver defined mentoring benefits. Facilitators can create programs, program enrollments, and benefits by launching workflows from the app navigation menu. A support program can include a Mentoring benefit type, a benefit, and an intake assessment.","Institutions can publish mentoring programs in an Experience Cloud portal so learners can review program details and self-enroll. When a learner enrolls in a mentoring program, Education Cloud automatically enrolls the learner in the associated mentoring benefit and creates a benefit assignment. Mentors can register in the mentor portal as providers of benefits offered by the program.","Programs can include assessments with predefined questions. The assessment appears during portal enrollment, and automation saves responses as records related to the program enrollment. Mentoring facilitators review these responses to determine whether the program meets the learner's needs and how best to provide support."],connections:[]},
    {id:"mentor-profiles",name:"Mentor & Mentee Profiles",icon:"\u{1F464}",desc:"Mentor & Mentee Profiles identify the roles, preferences, and interests of mentoring participants in Education Cloud. Each mentoring profile is associated with a contact and a related program enrollment or provider offering. Profile information can include subject area, meeting channel, availability, skills, and location for use when comparing participants.",tags:["MentoringProfile"],docs:["A mentoring profile provides information that helps a facilitator connect a mentee with a suitable mentor. Institutions can add fields relevant to their matching process, such as industry or field of study, virtual or in-person preference, available days and times, skills, and location. Lookup Relationship, Master-Detail Relationship, and System fields aren't supported when comparing mentoring participants.","A mentor is represented as a provider of a mentoring benefit through a provider offering. A person becomes a mentee by enrolling in a mentoring program or by having a related program enrollment identified in the mentoring profile. Mentors can include senior students, staff members, alumni, or outside organizations, while mentees can include students or new staff members.","Facilitators can create mentoring profile records manually by selecting a contact and the related program enrollment or provider offering. Institutions can also build a record-triggered flow that maps assessment responses to mentoring profile fields and creates or updates the appropriate mentor or mentee profile. Creating a mentoring profile record doesn't create the user profile required for portal access."],connections:[{"planet":"records","desc":"Profiles reference person account records"}]},
    {id:"mentor-matching",name:"AI-Powered Matching",icon:"\u{1F916}",desc:"AI-Powered Matching represents the Education Cloud process for comparing mentor and mentee information and selecting a suitable mentor. Assessments capture participant needs, interests, goals, and preferences, while mentoring profiles provide fields for comparison. Facilitators use the Mentor Comparison screen flow and the benefit assignment record to complete the match.",tags:["MentoringProfile"],docs:["Mentoring assessments help facilitators understand a mentee's requirements and identify a mentor who can address the mentee's needs and goals. Assessment responses can populate mentoring profile fields through a record-triggered flow. The resulting profile data can then be used in the Mentor Comparison screen flow to compare potential mentors with a mentee.","Institutions determine which profile fields are relevant to comparison. Documented examples include industry or field of study, meeting channel, available days and times, skills, and location. These fields are added to the mentoring profile record page and mapped from assessment responses as needed.","Facilitators finalize a mentoring connection on the benefit assignment record by specifying the mentor as the provider. The Mentoring app home page identifies benefit assignments that don't yet have a mentor assigned, helping facilitators focus on unmatched mentees. The assignment record then provides access to participant details, mentoring activities, assessments, alerts, notes, tasks, and related records."],connections:[]},
    {id:"benefit-assignment",name:"Benefit Assignment & Tracking",icon:"\u{1F4E6}",desc:"Benefit Assignment & Tracking manages the mentoring support assigned to an enrolled mentee in Education Cloud. Enrollment in a mentoring program creates a benefit assignment that facilitators use to connect the mentee with a benefit provider. The assignment record centralizes participant details, mentoring activity history, assessments, alerts, action plans, and other relationship information.",tags:["MentoringBenefit","MentoringBenefitAssignment"],docs:["Mentoring benefits describe the guidance or support delivered through a program, such as networking, skill development, academic guidance, or career development. A benefit is associated with a program and benefit type and can include availability dates, a unit of measure, enrollment count, minimum and maximum amounts, a benefit manager, and a goal definition. A benefit can also allow portal users to register as providers.","When a mentee enrolls in a mentoring program, Education Cloud creates a benefit assignment record. A facilitator connects the mentee to a mentor by setting the provider on that assignment. Provider offering records identify the person or organization that delivers a particular benefit, and mentors can create these records by registering through an Experience Cloud portal.","The benefit assignment record page supports ongoing management of the mentoring relationship. Facilitators can review mentee and mentor contact information, see a timeline of mentoring activities, create alerts, add notes, create tasks, send email, and work with related assessments, action plans, and interaction summaries. The Mentoring app home page also shows benefit assignments, benefit providers, and current or upcoming tasks."],connections:[{"planet":"success","desc":"Mentoring outcomes feed student success metrics"}]}
  ],
  dataFlow: ["Create a mentoring program, define its mentoring benefits, and publish it for enrollment.","Enroll mentees and register mentors as benefit providers through the appropriate Experience Cloud portal.","Link mentor and mentee profiles to their person records and capture interests, goals, preferences, and availability.","Review assessment and profile information, compare potential mentors, and assign a provider to the mentee's benefit assignment.","Schedule mentoring sessions as appointments and track activities, assessments, and benefit delivery.","Evaluate mentoring outcomes as student success metrics through the institution's outcome strategy."],
  connections: [{"planet":"records","desc":"Mentor/mentee profiles linked to person records"},{"planet":"success","desc":"Mentoring outcomes tracked as success metrics"},{"planet":"appointments","desc":"Mentoring sessions scheduled as appointments"}]
},

alumni: {
  packages: ["educationcloud"],
  name: "Alumni & Advancement",
  icon: "\u{1F3C5}",
  color: "#ec4899",
  description: "Alumni & Advancement in Education Cloud extends institutional relationships beyond graduation by keeping alumni status and engagement connected to person records. It brings together alumni outreach, portal participation, career and learning information, volunteerism, fundraising campaigns, gifts, and commitment fulfillment, with contributed funds connected to institutional finance. Data 360, advancement dashboards, and giving reports help staff understand philanthropic and non-philanthropic engagement across the institution. The alumni engagement agent uses this connected context to support outreach, while the alumni portal provides self-service access for giving and volunteering.",
  components: [
    {id:"alumni-engagement",name:"Alumni Engagement",icon:"\u{1F465}",desc:"Alumni Engagement gives coordinators a centralized Education Cloud workspace for maintaining alumni information and understanding each person’s relationship with the institution. Alumni remain represented through person records, while engagement data can include events, communications, volunteerism, philanthropy, occupations, learning achievements, alerts, cases, and portal participation. Data 360 identity resolution, calculated insights, and generative AI summaries help staff interpret activity assembled from multiple institutional sources. Advancement dashboards provide institution-wide KPIs that can be filtered by college or department.",tags:["Account"],docs:["The Alumni Relations app lets staff review, update, and enter alumni information in a central CRM location. Because Education Cloud stores individuals such as alumni as Person Accounts, post-graduation engagement can remain connected to the person’s institutional record and alumni status. Experience Builder supports an alumni community where constituents can create portal accounts and participate in alumni services, including giving and volunteering.","Alumni Engagement Metrics combines Data 360 with Einstein generative AI to track varied interactions and translate them into concise engagement summaries. Identity resolution links data from multiple sources into unified profiles, while calculated insights cover comprehensive engagement, philanthropic status, and giving status. Configurable summaries can address events and activities, personal communications, institutionally valued volunteer roles, and philanthropic contributions aligned with institutional goals.","The Alumni Relations Console can display the Alumni Engagement Insights dashboard on an Education Cloud home page. Its KPIs include alumni and portal-account counts, open alerts and cases, occupations, and learning achievements earned at the institution or elsewhere. Staff can view results across the institution or filter them by college or department, and scheduled or manual analytics refreshes keep dashboard data current."],connections:[{"planet":"records","desc":"Alumni are former students with person records"},{"planet":"experience","desc":"Alumni portal for community engagement"}]},
    {id:"gift-management",name:"Gift Management",icon:"\u{1F381}",desc:"Gift Management supports Education Cloud advancement teams in engaging donors and operating institutional gift processes. GiftTransaction records connect donations to donors and can also associate transactions with campaigns, designations, outreach sources, tributes, refunds, and soft credits represented in the fundraising data model. Gift-entry configuration and batch defaults help staff apply common values consistently and reduce entry errors. Data 360 can harmonize gift transactions for segmentation, calculated insights, analytics, and AI-grounded alumni engagement summaries.",tags:["GiftTransaction"],docs:["Fundraising in Education Cloud provides configurable features, page layouts, and gift-operation processes for managing gifts and supporting advancement programs. Gift batches can use default values to apply common information more quickly and with fewer entry errors. The Gift Entry Grid can also accept configured column data and write GiftEntry field values back to a selected row.","GiftTransaction is included in the Fundraising data bundle and among the fundraising Data 360 data model objects. Data mapping connects imported source fields to the relevant Data 360 objects before the records are used for segmentation, activation, analytics, or other operations. Alumni Engagement Metrics can query gift transactions by donor and transaction date, then use transaction details as grounding data for philanthropic summaries.","Gift transactions can support related stewardship records such as tributes. A GiftTribute can be created for a transaction and can capture tribute type, honoree information, and the associated GiftTransactionId. Advancement gift data also connects to institutional finance so contributed funds can support scholarships, research, facilities, academic programs, and other institutional priorities."],connections:[{"planet":"financials","desc":"Gift funds connect to institutional finance"}]},
    {id:"gift-commitments",name:"Pledges & Commitments",icon:"\u{1F4DD}",desc:"Pledges & Commitments represents promised giving and its associated fulfillment schedule in Education Cloud. GiftCommitment and GiftCommitmentSchedule are included in the fundraising data model, and gift transactions can identify installments associated with a commitment. Staff can compare the commitment total with received amounts and use scheduled dates to manage fulfillment over time. Commitment and transaction data can be harmonized in Data 360 with other advancement records.",tags:["GiftCommitment"],docs:["A GiftCommitment records the donor’s promised total, the amount received, and the dates and payment schedule associated with the commitment. Related GiftCommitmentSchedule records represent the scheduled fulfillment structure. These records are part of the fundraising Data 360 model and are mapped with accounts, campaigns, gift transactions, and other advancement data.","Gift-entry processes can look for an unpaid GiftTransaction associated with a donor’s commitment. When a matching installment is found, the process can return the transaction identifier, name, original amount, due date, campaign, and outreach source for use in the gift-entry row. This connection lets staff apply a received gift to an existing scheduled commitment transaction rather than treating it as an unrelated contribution."],connections:[]},
    {id:"volunteering",name:"Volunteer Management",icon:"\u{270B}",desc:"Volunteer Management in Education Cloud helps institutions administer volunteer programs, improve the volunteer experience, track contributed hours, and report program metrics. An Experience Cloud portal can publish opportunities and let volunteers browse, search, and sign up. Volunteer activity can contribute to an alumnus’s overall engagement profile alongside events, communications, and philanthropic giving. Data 360 calculated insights can classify and summarize volunteerism for relationship-building by alumni staff.",tags:["VolunteerActivity"],docs:["Volunteer Management streamlines the administration of institutional volunteer programs and provides a way to track hours and report metrics. Institutions can create an Experience Cloud portal that displays available opportunities to constituents. Volunteers can browse and search those opportunities and sign up through the portal.","Alumni Engagement Metrics treats volunteerism as a distinct form of engagement. Flow-based summaries can describe volunteer roles that are endorsed and highly valued by the institution, while calculated insights can count volunteerism activities and derive a corresponding engagement status. Coordinators can use this information with event, communication, and philanthropic data to understand an alumnus’s broader involvement."],connections:[{"planet":"mentoring","desc":"Alumni volunteers serve as mentors"}]},
    {id:"fundraising",name:"Fundraising Campaigns",icon:"\u{1F4C8}",desc:"Fundraising Campaigns supports advancement efforts that organize donor outreach and connect gifts with institutional priorities. Campaign records are included in the mapped fundraising bundle and can be associated with gift transactions and outreach source codes during gift entry. Education Cloud fundraising configuration helps institutions engage donors, manage gifts, and drive advancement programs. Campaign and giving data can feed advancement dashboards and giving reports while related funds connect to institutional finance.",tags:["Campaign"],docs:["Education Cloud provides Fundraising, Alumni Relations, and Data 360 capabilities for institutional advancement and development operations. Fundraising efforts can secure resources for scholarships, financial aid, faculty support, research, infrastructure, technology, and academic programs. Connecting campaigns and gifts to these priorities helps advancement teams align resource development with institutional goals.","The fundraising data bundle maps Campaign with Account, GiftCommitment, GiftTransaction, Opportunity, OutreachSourceCode, and other fundraising records. Gift-entry processes can populate campaign and outreach-source information for a donor or use those values from a matching unpaid commitment installment. These associations preserve campaign context as gifts are entered and processed.","Advancement analytics can use harmonized campaign, donor, and gift data to report engagement and giving outcomes. Data 360 calculated insights provide measures such as philanthropic status and status of giving, and gift transactions can ground generative AI summaries for staff. The alumni engagement agent can use this connected context to support alumni outreach while dashboards and giving reports provide operational visibility."],connections:[{"planet":"analytics","desc":"Giving analytics and advancement dashboards"}]}
  ],
  dataFlow: ["Track alumni status and engagement context on each person record.","Offer alumni portal access for giving, volunteer opportunity discovery, and sign-up.","Record gifts, commitments, campaign associations, and volunteer activity against the appropriate constituent.","Connect received gift funds and fulfillment activity to institutional finance.","Harmonize advancement data in Data 360 and refresh advancement dashboards and giving reports.","Use the alumni engagement agent and engagement insights to guide personalized outreach."],
  connections: [{"planet":"records","desc":"Alumni status tracked on person records"},{"planet":"financials","desc":"Gift funds connect to institutional finance"},{"planet":"agentforce","desc":"Alumni engagement agent manages outreach"},{"planet":"experience","desc":"Alumni portal for giving and volunteering"},{"planet":"analytics","desc":"Advancement dashboards and giving reports"}]
},

appointments: {
  packages: ["educationcloud"],
  name: "Appointments",
  icon: "\u{1F4C5}",
  color: "#14b8a6",
  description: "Appointments provides Education Cloud with a centralized, self-service system for scheduling and managing meetings across institutional departments. Learners can view staff availability and book scheduled, drop-in, in-person, phone, or virtual appointments, while staff can schedule on behalf of learners from student person records. Appointment scheduling supports student success and mentoring services, and it can document advising required before registration. Configured topics, cases, success teams, service resources, territories, engagement channels, and shifts determine which appointment options are available.",
  components: [
    {id:"appointment-scheduling",name:"Appointment Scheduling",icon:"\u{1F4C5}",desc:"Appointment Scheduling provides a centralized Education Cloud experience for learners and staff to find, book, and manage appointments across institutional departments. Learners can schedule through an Education Portal, while staff can schedule on a learner’s behalf from the learner’s person record. Available appointments are filtered by configured topics, success teams, staff resources, territories, engagement channels, and shifts. The resulting service appointments can support advising, admissions, student success, mentoring, and other institutional services.",tags:["ServiceAppointment"],docs:["Education Cloud uses the appointment scheduling data model to configure appointment topics, assign staff, manage availability, and create service appointments. Work Type Groups and Work Types represent topics and their appointment details, such as duration, category, supported channels, and territories. Appointment categories distinguish scheduled, drop-in, and group appointments. Skills can further help learners identify resources with the expertise needed for a topic.","Learners access scheduling through an Experience Cloud site, while staff can schedule from the learner’s person account record. The self-service workflow uses the learner’s existing cases and success team configuration to determine which assigned advisors, assigned teams, and bookable support pools are available. Learners and staff can schedule only for learners who have an existing related case. Staff can also book an appointment with a team that isn’t assigned to the learner when the applicable case configuration permits it.","Administrators can use the Manage Appointments component to configure appointment topics, staff members, engagement channels, appointment categories, operating hours, territories, and success teams. Education Cloud also provides portal components that display past and upcoming appointments and launch the scheduling workflow. Sharing settings, field-level security, and permission sets control access for staff and portal users. The scheduling experience is available on desktop and supported mobile devices."],connections:[{"planet":"enrollment","desc":"Advising appointments precede course registration"},{"planet":"success","desc":"Advising sessions support student success"}]},
    {id:"staff-availability",name:"Staff Availability",icon:"\u{1F464}",desc:"Staff Availability models when and where service resources can accept appointments and which topics and engagement channels they support. Education Cloud uses shifts associated with a staff member’s service territory to determine available time slots. Advisors can manage their own availability and, when permitted, the availability of colleagues through the Manage Availability component. Availability can be configured for multiple territories, channels, topics, dates, times, and recurrence patterns.",tags:["ServiceResource","ServiceTerritory"],docs:["Staff members must be represented as active service resources before they can be assigned to appointments. Each service resource can be associated with a primary service territory and one or more secondary territories. Service territories commonly represent campuses or other locations, but they can also group appointments by department or topic. A staff member who works in different locations or uses different channels on different days can be modeled through these territory and shift relationships.","Education Cloud uses shifts, rather than service territory operating hours, to calculate staff availability. A shift specifies the staff member, territory, time slot type, availability status, start and end times, supported appointment topics, and engagement channels. Administrators must enable the scheduling policy option that uses the service territory member’s shift. Because availability is based on shifts and the absence of shifts, non-working days and time off must be reflected in shift configuration.","The Manage Availability page guides advisors through adding and maintaining availability. Administrators can optionally filter topics by case team roles so that the displayed topics reflect the selected service resource’s roles in predefined case teams. Success team records connect advising case record types and support pools to scheduling availability. To appear for support-pool scheduling, an advisor must belong to the associated predefined case team, be configured as a service resource, and be connected through the applicable success team record."],connections:[]},
    {id:"waitlist-management",name:"Waitlist & Walk-ins",icon:"\u{23F3}",desc:"Waitlist & Walk-ins supports in-person drop-in services and the management of learners who arrive for consultations without a scheduled time. Appointment categories identify topics as drop-in or scheduled, and shifts determine when staff members offer drop-in availability. Education Cloud can display drop-in times on staff profiles and in the learner portal. Waitlists require the Drop In Appointment setting, although that setting isn’t required merely to configure drop-in availability.",tags:["ServiceAppointment"],docs:["To expose drop-in availability, create a shift that supports drop-ins and includes at least one in-person engagement channel. The shift must not support all topics; if it includes both drop-in and scheduled topics, Education Cloud displays only the drop-in topics. Institutions that offer both formats for the same service can create separate topics, such as a drop-in topic and a scheduled topic. Drop-in categories and their related topic templates are used when filtering available slots.","Lobby Management for Drop In Appointments helps staff manage learners who visit a location for an in-person consultation with an advisor. The Drop In Appointment setting is required when the institution uses waitlists. By default, Education Cloud displays drop-in availability for the next seven days, and administrators can customize the range up to ten days. Staff availability remains dependent on configured shifts, including any shifts omitted for holidays or other time away."],connections:[]},
    {id:"virtual-appointments",name:"Virtual Appointments",icon:"\u{1F4F9}",desc:"Virtual Appointments enables learners and staff to meet through configured remote engagement channels. After Salesforce Scheduler is configured for Education Cloud, institutions can integrate the AWS Chime SDK to provide audio and video capabilities in the learner portal. Staff can offer different channels by topic, location, and shift, including virtual service on selected days. Learners can join eligible virtual sessions from their appointment view.",tags:["ServiceAppointment"],docs:["Engagement Channel Types define how staff connect with learners, including channels such as phone, video, and in-person meetings. A staff member can support multiple channels across different locations, topics, and shifts. Topic templates are mapped to engagement channels so that Education Cloud can filter the appointment options shown to learners. The portal displays the selected appointment channel and location with the scheduled appointment.","When AWS Chime is configured, users can start a video call directly from the appointment utility. For video calls that use an external service, Education Cloud displays the information stored in the Appointment Booking URL field. A learner can join when the service appointment status is Scheduled or In Progress and the current time falls between the appointment’s Earliest Start Permitted and Due Date values. Past and upcoming appointments remain visible in the appointment experience, while canceled appointments aren’t shown to learners."],connections:[{"planet":"mentoring","desc":"Mentoring sessions use appointment scheduling"}]}
  ],
  dataFlow: ["Configure appointment topics, engagement channels, service territories, success teams, and active staff service resources.","Publish staff availability through shifts that specify supported territories, topics, channels, dates, and times.","Reference the learner’s student person record and related case when identifying eligible advisors, teams, and support pools.","Schedule advising appointments that support student success and satisfy advising required before registration, and use the same scheduling capability for mentoring sessions.","Create and manage the ServiceAppointment through its scheduled, drop-in, waitlist, in-person, phone, or virtual experience.","Update appointment status and retain past and upcoming appointment information for learner and staff follow-up."],
  connections: [{"planet":"enrollment","desc":"Advising required before registration"},{"planet":"records","desc":"Appointments reference student person records"},{"planet":"success","desc":"Advising appointments support student success"},{"planet":"mentoring","desc":"Mentoring sessions use appointment scheduling"}]
},

analytics: {
  packages: ["educationcloud"],
  name: "Education Analytics",
  icon: "\u{1F4CA}",
  color: "#f97316",
  description: "Education Analytics uses CRM Analytics in Education Cloud to create and embed customized dashboards and institutional KPIs for directors, recruiters, reviewers, admissions officers, and advisors. It provides insights into recruitment, admissions, learner engagement, academic activity, advisor effectiveness, and student success. Its connected scope also includes revenue and financial aid analytics, advancement and giving dashboards, and Agentforce performance monitoring. Administrators configure access, refresh analytics data, and place role-appropriate dashboards in Education Cloud app consoles.",
  components: [
    {id:"director-insights",name:"Director Insights",icon:"\u{1F3E2}",desc:"Director Insights provides institution-level CRM Analytics dashboards for recruitment and admissions and for student success. Recruitment and admissions directors can monitor application volume, reviews, decisions, yield, requests for information, and lead sources. Student success directors can evaluate enrollment, academic performance, advisor capacity, appointment utilization, alerts, and care plans. Dashboards can be embedded in role-specific Education Cloud consoles and filtered to compare performance across periods.",tags:[],docs:["For recruitment and admissions, directors use the Recruitment and Admissions Insights dashboard to examine the admissions pipeline and application distribution by stage, program, and academic year. Its KPIs include applications by status, total applications, application reviews by status, decision outcomes, yield and admission efficiency, responses to requests for information, and leads by source. Directors can use these measures to assess conversion from applications to admissions and from admissions to enrollment. The dashboard can be added to a Recruitment & Admissions home page with the Education Analytics Dashboard component in Lightning App Builder.","For student success, the Director Insights dashboard includes Institutional Overview, Student Success, and Advisor Insights pages. These pages show measures such as student counts, advisor-to-student ratio, average cumulative grade point average, alerts, care plans, appointments, and appointment utilization and cancellation rates. Advisor analysis identifies top- and least-performing advisors and shows utilization and cancellation rates for each advisor. Directors can filter information by academic term and compare results with a previous period."],connections:[]},
    {id:"recruitment-analytics",name:"Recruitment Analytics",icon:"\u{1F4C8}",desc:"Recruitment Analytics provides dashboards and KPIs for monitoring recruitment and admissions activity in Education Cloud. It analyzes the recruitment funnel through application stages, reviews, decisions, yield, requests for information, and lead sources. Role-specific dashboards support directors, recruiters, reviewers, and admissions officers in assessing pipeline progress and admission efficiency. Institutions can embed these dashboards in Recruitment & Admissions app consoles.",tags:[],docs:["The Recruitment and Admissions Insights dashboard presents application and recruitment data in multiple KPI-based panes. It shows application counts by status, total applications for a selected period, review status, finalized decision outcomes, and yield and admission efficiency. It also reports responses to requests for information and the lead sources associated with generated applications. These measures help staff evaluate the admissions pipeline and prioritize engagement.","Users can filter admissions data by application type and application creation date and compare results with a previous period. A director or admissions console can display the Recruitment and Admissions Insights dashboard, while a recruiter console can display the Recruitment Insights dashboard. Administrators add the Education Analytics Dashboard component through Lightning App Builder and select the appropriate dashboard. The page is then activated for the Recruitment & Admissions app and assigned to the required profiles."],connections:[{"planet":"recruitment","desc":"Recruitment funnel data feeds analytics"}]},
    {id:"student-success-metrics",name:"Student Success Metrics",icon:"\u{1F3C6}",desc:"Student Success Metrics provides analytics for institutional performance, learner support activity, and advisor effectiveness. Dashboards cover student enrollment, cumulative grade point average, alerts, care plans, appointments, and advisor service utilization. Directors receive institution-level and advisor-level views, while advisors can monitor care plans, active alerts, and appointment activity. Academic-term filters and period comparisons help users evaluate changes over time.",tags:[],docs:["The Director Insights dashboard supports annual monitoring of student performance and advisor efficiency. Its Institutional Overview page includes total students, students enrolled in advisor services, advisor-to-student ratio, average cumulative grade point average, and historical institutional performance. The Student Success page analyzes alerts, care plans, appointments, resolution time, and students without advisor appointments. The Advisor Insights page evaluates advisor performance and appointment utilization and cancellation rates.","The Advisor Insights dashboard focuses on student care plan programs, alerts, and advisor appointments. Advisors can identify care plans and active alerts that need attention, including alerts organized by due date. Appointment analysis shows upcoming appointments and distributions by case record type, appointment status, channel, and topic type. It also compares appointment utilization with a previous period."],connections:[{"planet":"success","desc":"Success tracking data powers analytics"}]},
    {id:"financial-analytics",name:"Financial Analytics",icon:"\u{1F4B0}",desc:"Financial Analytics connects revenue and financial aid analytics with the broader Education Analytics experience in Education Cloud. It supports institutional monitoring of financial-domain information through dashboards and key performance indicators. These insights complement recruitment, student success, advancement, and other institutional analytics.",tags:[],docs:["Financial Analytics brings revenue and financial aid analytics from the financials domain into the institutional analytics scope. The resulting information can be evaluated alongside other Education Cloud dashboards and KPIs. This connected view supports analysis of financial information in the context of the learner lifecycle.","Administrators must configure Education Analytics and enable CRM Analytics before users can access its dashboards. Required access includes Education Cloud Full Access and CRM Analytics for Education Cloud administration permissions for users who enable and configure the app. Administrators can assign additional permission sets to users who view or manage analytics."],connections:[{"planet":"financials","desc":"Financial data feeds revenue dashboards"}]}
  ],
  dataFlow: ["Configure Education Analytics, enable CRM Analytics, and assign the required permissions.","Connect recruitment funnel and student success data to the analytics experience.","Include revenue and financial aid analytics and advancement and giving dashboards.","Incorporate Agentforce performance monitoring into the connected analytics scope.","Refresh the analytics connection and run the documented Education Analytics recipes.","Embed role-appropriate dashboards in Education Cloud app consoles."],
  connections: [{"planet":"recruitment","desc":"Recruitment funnel dashboards"},{"planet":"financials","desc":"Revenue and financial aid analytics"},{"planet":"alumni","desc":"Advancement and giving dashboards"},{"planet":"agentforce","desc":"Agent performance monitoring"}]
},

agentforce: {
  packages: ["educationcloud"],
  name: "Agentforce",
  icon: "\u{1F916}",
  color: "#a855f7",
  description: "Agentforce for Education Cloud applies generative AI across recruitment, admissions, student success, student financials, financial aid, and alumni engagement. Education-specific agents and subagents answer questions, automate selected actions, summarize records, and recommend follow-up using institutional knowledge, CRM data, and Data 360 data. Institutions configure permissions, data access, search resources, prompt templates, messaging channels, and escalation paths to align agent behavior with their policies. Usage metrics, audit information, and dashboards help institutions monitor agent activity and consumption.",
  components: [
    {id:"recruitment-agent",name:"Recruitment Agent",icon:"\u{1F4E3}",desc:"The Recruitment Agent supports recruitment outreach by answering prospective learners’ questions about an institution, its programs, admissions processes, and campus opportunities. It can create academic interest records, register users for campus tours or events, and help begin applications. Responses can be grounded in institutional knowledge articles and Education Cloud data.",tags:[],docs:["The Recruitment Agent helps institutions assess and recruit prospective learners through conversational interactions. Its subagents can answer admissions and enrollment questions, provide learning program information, create academic interest records when a prospect requests contact, and start admissions applications. It can also help users register for campus tours, visits, and events.","Institutions ground responses with knowledge articles about learning programs, support programs, application processes, and campus information. Actions that use flows can be cloned and configured, particularly when the agent serves unauthenticated users. If a question requires personal attention or cannot be answered, institutions can configure escalation to a human representative and use an inquiry action to capture the request.","Administrators enable Education Cloud, Einstein Generative AI, and Agentforce before configuring the agent. The agent can be created for authenticated users or as a service agent for unauthenticated users, with appropriate permissions, sharing rules, data streams, search indexes, and knowledge access. It can then be connected to an Experience Cloud site or another supported messaging channel."],connections:[{"planet":"recruitment","desc":"Automates recruitment outreach sequences"}]},
    {id:"admissions-agent",name:"Admissions Agent",icon:"\u{1F4CB}",desc:"The Admissions Agent supports application status Q&A and other admissions-related conversations for prospective learners, applicants, and staff. It uses institution-provided knowledge and Education Cloud application data to answer questions about programs, application processes, timelines, and enrollment. Configured actions can also help a learner start an application.",tags:[],docs:["Admissions capabilities are provided through the Student Recruitment Agent’s admissions and enrollment subagents and actions. The agent can retrieve learning program, academic term, and program-term application timeline information and use that information when answering questions or creating an admissions application. Application deadline responses can include the application close time when the corresponding data stream, search index, retriever, and prompt template are configured.","Knowledge articles ground answers about application processes, learning programs, support programs, and campus information. Because the knowledge-answering action is generally treated as public, institutions must ensure that articles used for unauthenticated conversations contain no non-public information. Questions that cannot be resolved by the agent can be escalated for personal attention.","Configuration includes enabling the agent, assigning required permissions, preparing application record types, and applying filters to application-creation actions. Administrators also create the required data streams and search resources and add the relevant subagents from the asset library. Authenticated and unauthenticated experiences use different agent templates and can be connected to separate Experience Cloud sites."],connections:[{"planet":"admissions","desc":"Answers applicant questions about their application"}]},
    {id:"success-agent",name:"Student Success Agent",icon:"\u{1F31F}",desc:"The Student Success Agent supports advisors by summarizing advising cases, answering questions about campus resources and policies, and suggesting proactive follow-up. These capabilities help staff identify learners whose cases or circumstances require attention and determine appropriate next steps. Student goal guidance can also recommend courses, support programs, and involvement groups based on learner information and assessment insights.",tags:[],docs:["Student advising subagents help advisors quickly understand advising cases and respond to learner questions. Standard actions can find and summarize advising cases and locate campus resources, while knowledge-grounded responses can address institutional policies. The agent can suggest next-best actions, such as creating to-dos or cases, to support proactive follow-up for learners who may need assistance.","Advising responses are grounded in institutional data and knowledge. Policy answers use knowledge articles, while campus-resource searches use an Einstein search retriever over data made available through configured data streams and a Data 360 data model object. Institutions must review the student information used for summaries, apply appropriate access controls, and comply with institutional privacy requirements.","Student goal capabilities provide SMART goal recommendations based on a learner’s profile, preferences, and assessment insights. Recommendations can include relevant courses, support programs, and involvement groups, but they are guidance rather than directives or a substitute for human advisors, mentors, or counselors. Institutions should disclose how learner data is used, communicate the variability and limitations of generative AI, and define escalation workflows for sensitive or high-risk interactions."],connections:[{"planet":"success","desc":"AI advising surfaces at-risk students"}]},
    {id:"financials-agent",name:"Student Financials Agent",icon:"\u{1F4B0}",desc:"The Student Financials Agent helps learners retrieve account balances and understand included fees. Related financial aid capabilities provide guidance about financial aid status, requirements, awards, cost estimates, and disbursements. Personalized responses depend on financial data ingested and mapped through Data 360 for Education Cloud.",tags:[],docs:["The Student Financials Agent answers learner questions about account balances and the fees that make up those balances. The Financial Aid Agent supports prospective learners, applicants, and current students with inquiries about financial aid status, requirements, and awards. Together, these capabilities give learners conversational access to financial and financial aid guidance.","Financial aid responses are grounded with data from an institution’s external financial aid management system. Administrators ingest and map that data to financial aid Data Model Objects in Data 360 for Education Cloud, modeling the lifecycle from application through disbursement. The same harmonized data also powers financial aid Lightning web components for staff and portal users.","Institutions can expose financial aid information through an Experience Cloud portal and configure a screen flow for inquiries. A Financial Aid Year Filter supplies data to the other financial aid components on a page and lets users select an award year. Portal components and the Financial Aid Agent for unauthenticated users require the applicable guest and portal access to Data 360."],connections:[{"planet":"financials","desc":"Handles billing and aid inquiries"}]},
    {id:"alumni-agent",name:"Alumni Agent",icon:"\u{1F3C5}",desc:"The Alumni Agent supports alumni engagement automation through generative AI responses and engagement insights grounded in CRM and Data 360 data. Institutions can summarize alumni and supporter engagement to help staff understand an individual’s relationship with the institution. These insights support more informed relationship-building with former learners and other supporters.",tags:[],docs:["Education Cloud can present alumni and supporter engagement through the Engagement Visualization component. The component displays Data 360 calculated insights, Einstein generative AI prompt responses, or both for an individual. Institutions can tailor the component to different alumni engagement use cases and place it on supported record pages.","Prompt responses can be grounded in CRM and Data 360 records, while Alumni Engagement Metrics provide calculated insights about alumni and supporter activity. Administrators configure the applicable data streams, data model objects, calculated insights, and prompt templates for the engagement information they want to surface. When configured, the resulting summaries give internal staff context for alumni relationship-building and engagement automation."],connections:[{"planet":"alumni","desc":"Manages alumni outreach and engagement"}]}
  ],
  dataFlow: ["Ground recruitment outreach in institutional knowledge and program data.","Answer admissions and application-status questions using configured application information.","Summarize advising cases and surface learners who need proactive support.","Guide learners through account-balance, fee, and financial aid questions.","Generate grounded alumni engagement insights for relationship-building.","Monitor agent usage through metrics, consumption tools, audit trails, and dashboards."],
  connections: [{"planet":"recruitment","desc":"Recruitment outreach automation"},{"planet":"admissions","desc":"Application status Q&A"},{"planet":"success","desc":"At-risk student identification"},{"planet":"financials","desc":"Financial aid guidance"},{"planet":"alumni","desc":"Alumni engagement automation"},{"planet":"analytics","desc":"Agent usage metrics and dashboards"}]
},

experience: {
  packages: ["educationcloud"],
  name: "Experience Cloud",
  icon: "\u{1F310}",
  color: "#64748b",
  description: "Experience Cloud provides the secure online portal foundation for Education Cloud constituents across recruitment, admissions, student services, financial self-service, and alumni relations. The configurable Education Portal template supplies education-specific pages and components for inquiries, applications, appointments, course registration, support services, financial information, alumni profiles, and directories. Institutions use permission sets, system permissions, audiences, sharing settings, and sharing sets to tailor content and record access for applicants, students, alumni, and people with overlapping roles. Experience Builder supports page, component, navigation, and theme configuration, while supported mobile access lets learners complete selected self-service activities on the go.",
  components: [
    {id:"student-portal",name:"Student Portal",icon:"\u{1F393}",desc:"The Student Portal provides enrolled learners with a secure, self-service Education Cloud experience for academic, support, appointment, and financial activities. Students can view learning program plans, connect with success teams, enroll in support programs, manage appointments, and work with care plans, goals, benefits, tasks, and action plans. With the required Advanced Academic Operations access, the portal can also support course registration and waitlists. Institutions can add student financial and financial aid components to present balances, awards, disbursements, and related information.",tags:[],docs:["The Education Portal template includes pages and components for common student activities. Its Learning Programs area lists the portal user’s learning program plans, while Success Team and Support Programs provide access to assigned resources and available services. Student success components also let learners view advisors, post questions, check availability, schedule appointments, manage action plans, and track career and life goals. Institutions add and configure these components with Experience Builder.","Advanced Academic Operations extends the student portal with course registration, waitlists, holds management, GPA calculation, and enrollment policy enforcement. Students require the Education Cloud Advanced Academic Operations for Experience Cloud permission set license and the applicable Experience Cloud permission sets. Every feature in the Advanced Academic Operations feature set uses Business Rules Engine and its quota capacity. Administrators must enable Academic Operations and Advanced Academic Operations before granting access.","Student financials can provide a Financial Status at a Glance component showing charges, adjustments, balance due, the next due date, and payment status. Financial aid pages use a required Financial Aid Year Filter that supplies data to other financial aid components and lets users select an award year. Optional financial aid components can present highlights, applications, checklists, awards, and disbursements, and the portal can link to an external financial aid system. Administrators must configure the required permissions, sharing access, and supporting financial or financial-aid services before publishing these experiences."],docUrl:"https://help.salesforce.com/s/articleView?id=sfdo.ec_set_up_an_education_portal.htm&language=en_US",connections:[{"planet":"enrollment","desc":"Course registration through the portal"},{"planet":"financials","desc":"Financial account access and payments"}]},
    {id:"applicant-portal",name:"Applicant Portal",icon:"\u{1F4CB}",desc:"The Applicant Portal supports Education Cloud recruitment and admissions self-service from registration and requests for information through application submission and tracking. Applicants can start applications, review statuses and details, complete assigned tasks, schedule appointments, and manage submitted applications. Dynamic application options are derived from active Program Term Application Timeline records and their related academic terms, learning programs, and application timelines. A separate configuration can enable parents, guardians, caregivers, and commissioned agents to apply on behalf of students.",tags:[],docs:["The Education Portal template provides Home, Applications, Requests for Information, and Appointments areas for applicants. Home displays created applications, requests for information, tasks, and appointments, while Applications lists existing applications and lets users start a new one. Applicants can raise and monitor requests for information and schedule appointments with institution staff. When an applicant registers through the learner portal, Education Cloud automatically creates a person account for that individual.","For dynamic applications, administrators add and configure the New Application and application-detail components in Experience Builder. New Application picklist values are filtered from qualifying Program Term Application Timeline records; related academic terms and learning programs must be active, and the associated application timeline must be open. Application settings can let applicants view and edit tasks before submission, submit after completing required tasks, provide a digital signature, and confirm that their information is accurate. After submission, applicants can view task details but can no longer edit them, and they can be allowed to withdraw an application.","Education Cloud also supports a dedicated applicant portal for third-party representatives. Parents, guardians, caregivers, and commissioned agents can use configured OmniStudio components to manage students whom they represent and submit applications on their behalf. Institutions should create a separate portal for this use case if they already operate a portal where applicants apply for themselves. A sharing set must grant third-party users access to the records required for their work."],connections:[{"planet":"admissions","desc":"Application tracking and document submission"}]},
    {id:"alumni-portal",name:"Alumni Portal",icon:"\u{1F3C5}",desc:"The Alumni Portal gives former learners a secure Education Cloud experience for maintaining profiles and connecting with the institution and other alumni. Alumni can populate personal information in an Alumni Profile and search public profiles through the directory. Institutions can use audiences and permission sets to present alumni-specific pages and components while also supporting people who have overlapping applicant, student, and alumni roles. This portal experience connects alumni self-service with the broader alumni relations process.",tags:[],docs:["The Education Portal template includes components designed for alumni alongside those for applicants and students. The Alumni Profile area lets portal users populate personal information to create their profiles, and the Directory provides a searchable list of public profiles. Alumni can therefore maintain a presence in the community and find other alumni from the institution. A single portal login can also serve alumni who are applying for continued learning or otherwise hold overlapping constituent roles.","Institutions can create processes and flows from templates to maintain Alumni Directory information. Staff can use current learner and alumni data to understand an alumnus’s involvement, create related alerts and activities, and monitor alumni-relations goals with KPI reports. Alumni-specific Experience Cloud components are part of a broader Education Cloud capability that gives staff a 360-degree view of learners from prospect through involved alumnus. Access to portal pages and components is controlled through the institution’s configured audiences and permissions."],connections:[{"planet":"alumni","desc":"Alumni community and giving portal"}]},
    {id:"mobile-experience",name:"Mobile Experience",icon:"\u{1F4F1}",desc:"Mobile Experience extends the Education Cloud learner portal to supported mobile devices so learners can access key self-service functions while away from a desktop. Learners can view care-plan and success-team details and schedule appointments with advisors on the go. Institutions configure and publish the same Experience Cloud site through Experience Builder, with role-based visibility determining which pages and components each user can access.",tags:[],docs:["Education Cloud student success components bring learner self-service functions into an Experience Cloud portal. On supported mobile devices, learners can view details of their care plans and assigned success teams and schedule appointments with advisors. The broader component set also supports past and upcoming appointments, advisor information, support programs, assessments, benefits, tasks, action plans, and goals. Available functions depend on the components that the institution adds and configures.","Administrators use Experience Builder to arrange portal pages, add Education Cloud components, customize navigation, and preview and publish the site. Audiences, permission sets, and system permissions work together to control page and component visibility for applicants, students, alumni, and users with overlapping roles. Portal users must have the applicable Education Cloud for Experience Cloud access and licenses, and the security model can also use organization-wide defaults and sharing sets. This configuration keeps mobile access aligned with the same role-based and record-level controls used by the rest of the portal."],connections:[]}
  ],
  dataFlow: ["Configure the Education Portal template and add the required Experience Cloud pages and components.","Assign licenses, permission sets, audiences, and sharing access for each constituent role.","Expose recruitment inquiry and event experiences and route prospects into admissions application tracking.","Enable student course-registration and financial self-service features when the required add-ons and permissions are configured.","Provide alumni profile and directory access through the alumni community portal.","Preview and publish the portal for authorized desktop and mobile users."],
  connections: [{"planet":"recruitment","desc":"Prospect inquiry and event portal"},{"planet":"admissions","desc":"Application tracking portal"},{"planet":"financials","desc":"Financial self-service portal"},{"planet":"alumni","desc":"Alumni community portal"}]
},

data360: {
  packages: ["educationcloud"],
  name: "Data 360",
  icon: "\u{1F5C3}",
  color: "#06b6d4",
  description: "Data 360 centralizes disparate student and education data for use with Education Cloud. It ingests information from institutional systems, maps source fields to a harmonized data model, and applies identity resolution to unify student person records from multiple sources. The resulting deduplicated learner profiles support calculated insights, analytics, automation, personalized experiences, and AI grounded in trusted institutional data. Education data kits accelerate implementation with packaged data streams, mappings, calculated insights, and identity resolution resources.",
  components: [
    {id:"data-consolidation",name:"Data Consolidation",icon:"\u{1F4E5}",desc:"Data Consolidation brings disparate learner and education data into a central Data 360 environment for Education Cloud. Institutions can ingest data from student information, learning management, enterprise resource planning, engagement, advancement, and campus systems. The consolidated data supports harmonization, unified learner profiles, analytics, automation, and trusted AI grounding.",tags:["DataStream"],docs:["Education Cloud uses Data 360 to connect and prepare large volumes of data from institutional systems. Student information systems can provide profiles, registrations, payments, attendance, and grades, while learning management systems can provide usage, interactions, and assessments. Enterprise resource planning systems contribute financial records, tuition and fee details, financial aid, billing, and holds. Institutions can also ingest data from systems for housing, dining, event registration, and other campus services.","Connect external sources to Data 360 and use data streams to collect and store their data. The Education data kit packages components such as data streams and calculated insights and provides bundles with prebuilt mappings to key Education Cloud data model objects. When deploying a data kit stream, administrators select the source org, bundle, data space, fields, and stream names before deployment. An Active status indicates that the deployed data streams are ready for subsequent processing."],connections:[]},
    {id:"identity-resolution",name:"Identity Resolution",icon:"\u{1F50D}",desc:"Identity Resolution links student person records from multiple data sources into unified profiles. An identity resolution ruleset contains match and reconciliation rules that determine how related source records are linked. Education Cloud data kits can provide a preconfigured ruleset, while implementations can also create rulesets for specific data sources and use cases.",tags:["IdentityResolutionRuleset","MatchRule"],docs:["The Education data kit includes an identity resolution ruleset with match and reconciliation rules for linking multiple sources of data into a unified profile. Implementations can also create a ruleset for the data platform after ingesting and mapping source records. For financial aid, the ruleset is created on the Individual object to match records from the financial aid system with Salesforce Person Accounts. After the ruleset is published and run, administrators can confirm that it produces a nonzero data consolidation rate.","Identity resolution depends on properly mapped person data. For financial aid, the Individual DMO must be populated before related email, phone, and address DMOs because those records link to the individual. The documented financial aid configuration matches records using a combination of fuzzy and exact name matching and exact normalized email matching. For calculated insights that contain the unified individual DMO, a Contact data stream must also be created and mapped for identity resolution."],connections:[{"planet":"records","desc":"Resolved identities create unified person records"}]},
    {id:"unified-records",name:"Unified Records",icon:"\u{1F464}",desc:"Unified Records represent consolidated learner identities created by linking related source records. They provide the unified learner profile that Education Cloud uses to connect information across the learner journey. Unified individual records and links can support calculated insights, engagement visualizations, analytics, and personalized experiences.",tags:["UnifiedIndividual"],docs:["Data 360 harmonizes imported institutional data into a unified learner profile. This profile gives institutions a central view for understanding and supporting current learners, engaging alumni, and preparing for future learners. Unified data can support reliable analytics and predictions, scaled automation, trusted AI grounding, and customized learner experiences. Identity resolution supplies the links between source records and the resulting unified profile.","Education Cloud components can use calculated insights related to an individual DMO, a unified individual, or a unified individual link. For example, the Engagement Visualization component can display calculated insights and generative AI prompt responses grounded in CRM and Data 360 data. Calculated insight queries can join source records through individual identity links to a unified individual. This structure enables metrics from multiple linked records to be grouped around one learner identity."],connections:[{"planet":"records","desc":"Unified records feed into person accounts"}]},
    {id:"data-mapping",name:"Data Mapping & Standards",icon:"\u{1F5FA}",desc:"Data Mapping & Standards aligns fields and objects from connected institutional sources with Data 360 data model objects. Mapping is required before imported education data can be used for segmentation, activation, analytics, or other Data 360 operations. Education-specific DMOs and data kit mappings provide a harmonized structure for learner, academic, engagement, advancement, and financial data.",tags:["DataStream"],docs:["After importing education data, administrators map it to the required Data 360 DMOs. Connecting a source allows Data 360 to access its objects and fields so that mapping sets can be created between the source and the Data 360 model. Education Cloud provides education-specific DMOs for data from learning management, student information, engagement, advancement, and enterprise resource planning systems. Harmonized DMO data can then be used to build segments, create calculated insights, and analyze key metrics.","The Education data kit supplies prebuilt mappings to key Education Cloud DMOs through bundles. Administrators must deploy fields required by mappings, along with formula fields and their source fields. When a source system uses values that differ from those expected by a DMO, a formula field on the data stream can transform the values during ingestion. Mapping the formula field instead of the original source field preserves the original value while making the ingested data compatible with Education Cloud components."],connections:[]}
  ],
  dataFlow: ["Connect institutional source systems to Data 360.","Deploy and activate data streams in the appropriate data space.","Map source objects and fields to the required data model objects.","Configure and run identity resolution rules to unify student person records.","Use unified learner profiles for insights, analytics, automation, and trusted AI grounding."],
  connections: [{"planet":"records","desc":"Identity resolution unifies student person records"}]
}

};
